      { qty: 5, unitPrice: 9500 },
      { qty: 1, unitPrice: 120000 },
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.deepEqual(totals, {
    subtotal: 5 * 9500 + 1 * 120000,
    discount: 0,
    total: 5 * 9500 + 1 * 120000,
  });
  assert.equal(totals.subtotal, 167500);
