  const addResult = addLine(result.value, { sku: 'LOGO-PACK', qty: 1 });

  assert.equal(addResult.ok, true);
  assert.equal(addResult.value.lines[1].discountPercent, 5); // Gold tier
});

test('addLine explicit discount overrides tier for new line', () => {
