  });

  assert.equal(result.ok, true);
  const text = renderInvoiceText(result.value);

  const lines = text.split('\n');
  // STICKER is 50 cents = €0.50
  assert.match(lines[2], /€0\.50/);
  // VAT line: 21% of 0.50 = 0.105, rounds to 0.11
  assert.match(lines[3], /€0\.11/);
});

